/**
 * ==================================
 * # Chamadas relacionadas a documentos
 * ==================================
 */

export async function getLinkedCedenteEsteiras(cedenteId: string): Promise<LinkedCedenteEsteira[]> {
    const res = await api.get(`/api/cedentes/${cedenteId}/esteiras/`);
    return res.data;
}

export async function getDocsFromEsteira(esteiraId: number): Promise<EsteiraDocs[]> {
    const res = await directApi.get(`/api/esteiras/${esteiraId}/documentos/`);
    return res.data;
}

export interface EsteiraExigenciaCondicional {
    id: number;
    documento_tipo: string;
    titular: string;
    label: string;
    obrigatorio?: boolean;
    ativa: boolean;
    documento_id?: number | null;
    esteira_id?: number;
    cedente_id?: string | null;
    extrato_id?: string | null;
}

export async function getEsteiraExigenciasCondicionais(
    esteiraId: number,
): Promise<EsteiraExigenciaCondicional[]> {
    const res = await directApi.get<{ exigencias_condicionais?: EsteiraExigenciaCondicional[] }>(
        `/api/esteiras/${esteiraId}/`,
    );
    return Array.isArray(res.data?.exigencias_condicionais)
        ? res.data.exigencias_condicionais
        : [];
}

export async function createEsteira(formData: Record<string, string>) {
    const res = await api.post(`/api/esteiras/`, formData);
    return res.data;
}

