export function CedenteDocsSection({ esteiraId, isPj, leadId, onDocsChange }: CedenteDocsSectionProps) {
    const [docs, setDocs] = useState<Dashboard2DocsCedenteRow[]>([]);
    const [loading, setLoading] = useState(false);
    const [outroDocTituloDraft, setOutroDocTituloDraft] = useState('');
    const [leadDocsSeed, setLeadDocsSeed] = useState<Dashboard2DocsCedenteRow[]>([]);
    const inputRef = useRef<HTMLInputElement | null>(null);
    const slotRef = useRef<string | null>(null);

    const slots = useMemo(() => (isPj ? SLOTS_PJ_MAIN : SLOTS_REP), [isPj]);

    useEffect(() => {
        let cancelled = false;
        if (!leadId) {
            setLeadDocsSeed([]);
            return () => {
                cancelled = true;
            };
        }

        void (async () => {
            try {
                const lead = await getLeadById(leadId);
                const rawDocs = lead?.documentacao_cedente_crm?.docs;
                if (!cancelled && Array.isArray(rawDocs)) {
                    setLeadDocsSeed(rawDocs as Dashboard2DocsCedenteRow[]);
                } else if (!cancelled) {
                    setLeadDocsSeed([]);
                }
            } catch {
                if (!cancelled) setLeadDocsSeed([]);
            }
        })();

        return () => {
            cancelled = true;
        };
    }, [leadId]);

    const refetch = useCallback(async () => {
        setLoading(true);
        try {
            const rows = await getDocsFromEsteira(esteiraId);
            const merged = dashboard2MergeEsteiraApiDocsIntoDocsCedente(
                rows as Dashboard2EsteiraDocRow[],
                isPj,
                leadDocsSeed,
            );
            setDocs(merged);
            onDocsChange?.();
        } catch {
            supportError(leadId);
        } finally {
            setLoading(false);
        }
    }, [esteiraId, isPj, leadDocsSeed, leadId, onDocsChange]);

    useEffect(() => {
        void refetch();
    }, [refetch]);

    const extras = docs.filter(
        (d) => d.tipoId == null || !slots.some((slot) => slot.id === d.tipoId),
    );

export function DocsSliderContextProvider({ children }: { children: React.ReactNode }) {
    const activeCedenteId = useBrokerStore((store) => store.activeCedente?.id);
    const activeCedenteType = useBrokerStore((store) => store.activeCedente?.tipo);
    const extratoId = useBrokerStore((store) => store.extratoId);

    // ==================
    // # React Query Hooks
    // ==================
    const { data: cedenteData } = useExtratoCedenteDataQuery(activeCedenteId);
    const { data: detailsExtratoData } = useQuery(useExtratoDataQueryOptions(extratoId));

    // Constants needing early definition
    const oficioEsteirasAtivas = detailsExtratoData?.esteira_documentos_por_cedente;

    const { data: linkedEsteirasCedente, isLoading: isLoadingLinkedEsteirasCedente } =
        useCedenteLinkedEsteirasQuery(activeCedenteId);

    const { data: linkedEsteirasRepresentante, isLoading: isLoadingLinkedEsteirasRepresentante } =
        useCedenteLinkedEsteirasQuery(cedenteData?.representante_legal?.id);

    // Computed Active Esteira IDs
    const activeCedenteEsteiraId = useMemo(
        () => getActiveEsteiraId(linkedEsteirasCedente, oficioEsteirasAtivas),
        [linkedEsteirasCedente, oficioEsteirasAtivas],
    );

    const activeRepresentanteEsteiraId = useMemo(
        () => getActiveEsteiraId(linkedEsteirasRepresentante, oficioEsteirasAtivas),
        [linkedEsteirasRepresentante, oficioEsteirasAtivas],
